            if (i == 0 || index != 0) {
                System.out.print(array[index] + " ");
            } else {
                System.out.println(array[index]);
            }
        }
    }

    public static void main(String[] args) {
        int[] myArray = {1, 2, 3};
        printArray(myArray, 0);
    }
}
